def _freeze_parameter_value(value: object) -> object:
    if isinstance(value, dict):
        return MappingProxyType(
            {str(key): _freeze_parameter_value(item) for key, item in value.items()}
        )
    if isinstance(value, list):
        return tuple(_freeze_parameter_value(item) for item in value)
    return value


@dataclass(frozen=True, slots=True)
class OptimizerDefaultCurrentizationV1:
    parameter_id: str
    parameter_symbol: str
    original_default_authority_class: str
    currentized_default_authority_state: str
    numeric_value_authority_class: str
    source_resolution_kind: str
    day1_seed_or_resolution_rule: str
    hard_bounds: str
    search_or_fit_constraint: str
    pinned_provider_or_library_version: str
    guess_prohibited: bool
    runtime_observation_may_not_use_static_seed: bool
    raw: Mapping[str, object]

    def __post_init__(self) -> None:
        required = (
            self.parameter_id,
            self.parameter_symbol,
            self.original_default_authority_class,
            self.currentized_default_authority_state,
            self.numeric_value_authority_class,
            self.source_resolution_kind,
            self.day1_seed_or_resolution_rule,
            self.hard_bounds,
            self.search_or_fit_constraint,
            self.pinned_provider_or_library_version,
        )
        if (
            any(not isinstance(value, str) or not value for value in required)
            or self.guess_prohibited is not True
            or type(self.runtime_observation_may_not_use_static_seed) is not bool
            or self.currentized_default_authority_state
            not in {
                "STATIC_VALUE_OR_DETERMINISTIC_RULE",
                "RUNTIME_BINDING_REQUIRED",
                "EXPLICIT_FAIL_CLOSED_POLICY",
                "NO_DEFAULT_REQUIRES_CALIBRATION",
            }
        ):
            raise ParameterPolicyError(
                ReasonCode.PARAMETER_OUT_OF_POLICY,
                "optimizer/default currentization row is incomplete",
            )


def _optimizer_default_currentization(
    row: object,
) -> OptimizerDefaultCurrentizationV1:
    if not isinstance(row, dict):
        raise ParameterPolicyError(
            ReasonCode.PARAMETER_OUT_OF_POLICY,
            "optimizer/default currentization row must be an object",
        )
    frozen = _freeze_parameter_value(row)
    assert isinstance(frozen, Mapping)
    return OptimizerDefaultCurrentizationV1(
        parameter_id=str(row["parameter_id"]),
        parameter_symbol=str(row["parameter_symbol"]),
        original_default_authority_class=str(
            row["original_default_authority_class"]
        ),
        currentized_default_authority_state=str(
            row["currentized_default_authority_state"]
        ),
        numeric_value_authority_class=str(row["numeric_value_authority_class"]),
        source_resolution_kind=str(row["source_resolution_kind"]),
        day1_seed_or_resolution_rule=str(row["day1_seed_or_resolution_rule"]),
        hard_bounds=str(row["hard_bounds"]),
        search_or_fit_constraint=str(row["search_or_fit_constraint"]),
        pinned_provider_or_library_version=str(
            row["pinned_provider_or_library_version"]
        ),
        guess_prohibited=bool(row["guess_prohibited"]),
        runtime_observation_may_not_use_static_seed=bool(
            row["runtime_observation_may_not_use_static_seed"]
        ),
        raw=frozen,
    )


_OPTIMIZER_DEFAULT_CURRENTIZATION_ROWS = tuple(
    _optimizer_default_currentization(row)
    for row in json.loads(_ST12B_OPTIMIZER_DEFAULT_CURRENTIZATION_JSON)
)
OPTIMIZER_DEFAULT_CURRENTIZATIONS: Mapping[
    str, OptimizerDefaultCurrentizationV1
] = MappingProxyType(
    {row.parameter_id: row for row in _OPTIMIZER_DEFAULT_CURRENTIZATION_ROWS}
)


@dataclass(frozen=True, slots=True)
class RuntimeParameterOwnerBindingV1:
    binding_id: str
    parameter_id: str
    parameter_symbol: str
    accepted_upstream_owner_id: str
    accepted_packet_or_snapshot_type: str
    schema_id: str
    schema_version: str
    exact_field_path: str
    required_clock_fields: tuple[str, ...]
    scope: str
    consumer: str
    producer_receipt_type: str
    value_state: str
    missing_stale_conflict_behavior: str
    raw: Mapping[str, object]

    def __post_init__(self) -> None:
        if (
            self.binding_id != f"RPVOB::{self.parameter_id}"
            or self.value_state != "RUNTIME_BINDING_REQUIRED"
            or self.schema_version != "1.0.0"
            or self.required_clock_fields
            != (
                "observed_time",
                "effective_time",
                "available_time",
                "received_time",
                "processed_time",
                "as_of_time",
            )
        ):
            raise ParameterPolicyError(
                ReasonCode.PARAMETER_BINDING_MISMATCH,
                "runtime parameter owner interface violates the frozen law",
            )


@dataclass(frozen=True, slots=True)
class CumulativeParameterPolicyV1:
    parameter_id: str
    parameter_symbol: str
    family_policy_contract_id: str
    current_numeric_authority_state: str
    source_resolution_kind: str
    target_kind: str
    canonical_component_or_service_id: str
    canonical_target_owner: str
    ultimate_owner: str
    ultimate_application_class: str
    application_binding_id: str
    ultimate_binding_id: str
    runtime_owner_binding_id: str | None
    crosswalk: Mapping[str, object]
    application: Mapping[str, object]
    ultimate_consumer: Mapping[str, object]
    repository_disposition: Mapping[str, object]

    def __post_init__(self) -> None:
        if (
            not self.parameter_id
            or not self.parameter_symbol
            or self.application_binding_id != f"PAB::{self.parameter_id}"
            or self.ultimate_binding_id != f"PUCB::{self.parameter_id}"
            or self.application["parameter_id"] != self.parameter_id
            or self.ultimate_consumer["parameter_id"] != self.parameter_id
            or self.crosswalk["parameter_id"] != self.parameter_id
            or self.ultimate_consumer["generic_compiler_is_sole_terminal_consumer"]
            is not False
        ):
            raise ParameterPolicyError(
                ReasonCode.PARAMETER_BINDING_MISMATCH,
                "cumulative parameter identity or ultimate consumer is inconsistent",
            )


